const overlay = document.createElement('div');
overlay.className = 'item-fullscreen';
overlay.style.cssText = `
  position: absolute !important;
  top: 0 !important; left: 0 !important;
  width: 100% !important; height: 100% !important;
  background: #ffffff !important;
  display: none !important;
  align-items: center !important;
  justify-content: center !important;
  z-index: 10 !important;
  padding: 40px !important;
  box-sizing: border-box !important;
  pointer-events: auto !important;
`;

const closeBtn = document.createElement('button');
closeBtn.type = 'button';
closeBtn.setAttribute('aria-label', 'Close');
closeBtn.textContent = '×';
closeBtn.style.cssText = `
  position: absolute; left: 20px; top: 20px;
  width: 48px; height: 48px; border: 2px solid #333; border-radius: 50%;
  background: #fff; color: #333; font-size: 28px; font-weight: 800;
  line-height: 1; cursor: pointer; z-index: 20;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
`;

const textEl = document.createElement('div');
textEl.style.cssText = `
  font-family: 'Segoe UI', system-ui, sans-serif;
  font-size: clamp(48px, 12vw, 120px);
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  color: #1a1a1a;
  max-width: 95%;
  cursor: pointer;
  user-select: none;
`;

overlay.appendChild(closeBtn);
overlay.appendChild(textEl);

const pageFrame = root.closest('.page-frame');
if (pageFrame) pageFrame.appendChild(overlay);
else root.appendChild(overlay);

const close = () => {
  overlay.classList.remove('open');
  overlay.style.display = 'none';
  textEl.textContent = '';
  textEl.style.color = '#1a1a1a';
};
closeBtn.addEventListener('click', close);
overlay.addEventListener('click', e => { if (e.target === overlay) close(); });

const COLORS = ['#1a1a1a', '#e63946', '#1d6fd6', '#E2571C', '#2a9d8f'];
let colorIdx = 0;
textEl.addEventListener('click', () => {
  colorIdx = (colorIdx + 1) % COLORS.length;
  textEl.style.color = COLORS[colorIdx];
});

root.querySelectorAll('.tap-item').forEach(el => {
  el.addEventListener('click', () => {
    const t = el.dataset.item || el.textContent.trim();
    textEl.textContent = t;
    colorIdx = 0;
    textEl.style.color = COLORS[0];
    overlay.classList.add('open');
    overlay.style.display = 'flex';
  });
});

if (!window.__phonicsItemEscapeInstalled) {
  window.__phonicsItemEscapeInstalled = true;
  window.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      document.querySelectorAll('.item-fullscreen.open').forEach(o => {
        o.classList.remove('open');
        o.style.display = 'none';
      });
    }
  });
}

